# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: emit
def emit(xs, offset=-1):
    return [v + offset for v in xs]

# region: digest
def digest(xs, factor=2):
    return [v * factor for v in xs]

# region: render
def render(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(render(digest(emit(sift(raw)))))

